const case004RouteHazards = {
  ARCHIVE_TERMINAL: ["1,0", "2,1", "0,2"],
  RECORDS_VAULT: ["1,1", "2,1", "1,3"],
  EMERGENCY_RECEIVER: ["1,0", "2,0", "2,2", "3,3"],
};

function isCase004RouteSafe(locationId, route) {
  if (
    !Array.isArray(route) ||
    route.length === 0 ||
    route[0] !== "0,0" ||
    new Set(route).size !== route.length
  ) {
    return false;
  }

  const hazards = case004RouteHazards[locationId] || [];
  return route.every((cell, index) => {
    const [x, y] = cell.split(",").map(Number);
    if (
      !Number.isInteger(x) ||
      !Number.isInteger(y) ||
      x < 0 ||
      x > 4 ||
      y < 0 ||
      y > 4 ||
      hazards.includes(cell)
    ) {
      return false;
    }
    if (index === 0) return true;
    const [previousX, previousY] = route[index - 1].split(",").map(Number);
    return Math.abs(x - previousX) + Math.abs(y - previousY) === 1;
  });
}

function isCase004RouteComplete(locationId, route) {
  const target = case004Locations.find(
    (location) => location.id === locationId,
  );
  return (
    Boolean(target) &&
    isCase004RouteSafe(locationId, route) &&
    route[route.length - 1] === `${target.x},${target.y}`
  );
}

