function getCase004ResponseOutcome(locationId, protocol) {
  const locationName = case004Locations.find(
    (location) => location.id === locationId,
  )?.name;
  const protocolOutcome = {
    ISOLATE:
      "The carrier is isolated. Its signal stops locally, but appears on the archive monitor.",
    PRESERVE:
      "The carrier is recorded without interference. A second set of timestamps appears in the log.",
    BROADCAST:
      "A warning is transmitted. The return channel repeats the warning before the transmission ends.",
  }[protocol];
  return locationName && protocolOutcome
    ? `${locationName}: ${protocolOutcome}`
    : "No response protocol was filed.";
}

