function getCase023Lead(classification, faultyStep) {
  return `CASE 023 // The second origin is linked to ${faultyStep}. The ${classification} carrier has crossed into the station network.`;
}

function getCase023Route(classification, faultyStep, frameId, action, response) {
  const expectedIds = case022RequiredEvidence[faultyStep] || [];
  const records = case022EvidenceByStep[faultyStep] || [];
  const originRecord = records.find((record) => record.id === expectedIds[0]);
  const relayRecord = records.find((record) => record.id === expectedIds[1]);
  const safeguard = case019Sequences[classification]?.find((step) => step.id === faultyStep);
  const steps = [
    { id: "ORIGIN", title: `SECOND ORIGIN // ${originRecord?.title}`, detail: originRecord?.detail || "The carrier begins at this source." },
    { id: "BREACH", title: `BYPASSED SAFEGUARD // ${safeguard?.title}`, detail: "The anomalous event passes through this compromised control." },
    { id: "RELAY", title: `STATION RELAY // ${relayRecord?.title}`, detail: relayRecord?.detail || "This record confirms the carrier entered the station network." },
    { id: "RETURN", title: "RETURN CARRIER", detail: `The signal exits through the ${frameId} channel after the ${action} / ${response} protocol.` },
  ];
  const optionOrder = ["RETURN", "ORIGIN", "RELAY", "BREACH"];
  const options = optionOrder.map((id) => steps.find((step) => step.id === id)).filter(Boolean);
  return { expectedIds: steps.map((step) => step.id), options };
}

function getCase024Lead(classification, faultyStep, response) {
  return `CASE 024 // The ${classification} carrier and ${faultyStep} breach converge. Final response required: ${response}.`;
}

